<?php
declare(strict_types=1);
namespace Annam;
/** CLI-only encrypted recovery archive. Passphrase is supplied privately by environment. */
final class Recovery {
    private static function password():string{$value=getenv('BACKUP_PASSPHRASE')?:'';if(strlen($value)<24)throw new \RuntimeException('Set BACKUP_PASSPHRASE to at least 24 random characters. Keep it separately from the backup.');return $value;}
    public static function seal(string $source,string $target):void {
        $salt=random_bytes(16);$prefix=random_bytes(8);$key=hash_pbkdf2('sha256',self::password(),$salt,300000,32,true);$in=fopen($source,'rb');$out=fopen($target,'xb');if(!$in||!$out)throw new \RuntimeException('Cannot open recovery files.');chmod($target,0600);$header="ANNAMBACKUP1\n".$salt.$prefix;fwrite($out,$header);$n=0;
        try{while(!feof($in)){$plain=fread($in,1048576);if($plain==='')break;$nonce=$prefix.pack('N',$n);$cipher=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag,$header.pack('N',$n));if($cipher===false)throw new \RuntimeException('Encryption failed.');fwrite($out,pack('N',strlen($cipher)).$tag.$cipher);$n++;}$cipher=openssl_encrypt('','aes-256-gcm',$key,OPENSSL_RAW_DATA,$prefix.pack('N',$n),$tag,$header.pack('N',$n));fwrite($out,pack('N',0).$tag);}finally{fclose($in);fclose($out);}
    }
    public static function unseal(string $source,string $target):void {
        $in=fopen($source,'rb');$out=fopen($target,'wb');chmod($target,0600);$magic="ANNAMBACKUP1\n";$header=fread($in,strlen($magic)+24);if(strlen($header)!==strlen($magic)+24||!str_starts_with($header,$magic))throw new \RuntimeException('Not an Annam encrypted backup.');$salt=substr($header,strlen($magic),16);$prefix=substr($header,-8);$key=hash_pbkdf2('sha256',self::password(),$salt,300000,32,true);$n=0;$done=false;
        try{while(!feof($in)){$len=fread($in,4);if(strlen($len)!==4)break;$length=unpack('N',$len)[1];if($length>1048576)throw new \RuntimeException('Invalid encrypted chunk.');$tag=fread($in,16);$cipher='';while(strlen($cipher)<$length&&!feof($in))$cipher.=fread($in,$length-strlen($cipher));if(strlen($tag)!==16||strlen($cipher)!==$length)throw new \RuntimeException('Truncated backup.');$plain=openssl_decrypt($cipher,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$prefix.pack('N',$n),$tag,$header.pack('N',$n));if($plain===false)throw new \RuntimeException('Backup authentication failed.');if(!$length){$done=true;if(fread($in,1)!=='')throw new \RuntimeException('Extra data after backup.');break;}fwrite($out,$plain);$n++;}if(!$done)throw new \RuntimeException('Incomplete encrypted backup.');}finally{fclose($in);fclose($out);}
    }
    public static function create(Database $db,string $target):array {
        if($db->isSqlite())return LocalRecovery::create($db,$target);
        if(!is_dir(Media::root())||!is_readable(Media::root()))throw new \RuntimeException('Complete media folder is missing or unreadable.');
        $inventory=(new Backup(new Store($db)))->references();if(getenv('APP_ENV')==='production'&&($inventory['missing']||$inventory['external']))throw new \RuntimeException('Resolve missing or external image references before making a complete production backup.');
        if(is_file($target)||is_link($target))throw new \RuntimeException('Choose a new output file.');$work=ANNAM_ROOT.'/storage/recovery-'.bin2hex(random_bytes(10));mkdir($work,0700,true);$data=$work.'/database.jsonl';$file=fopen($data,'wb');chmod($data,0600);$counts=[];
        try{$db->transaction(function()use($db,$file,&$counts){$db->rows('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY');$tables=$db->rows("SELECT tablename FROM pg_tables WHERE schemaname='public' ORDER BY tablename");foreach($tables as $table){$name=$table['tablename'];if(!preg_match('/^[a-z_][a-z0-9_]*$/D',$name))throw new \RuntimeException('Unsupported database table name.');$types=$db->rows("SELECT column_name,data_type FROM information_schema.columns WHERE table_schema='public' AND table_name=? ORDER BY ordinal_position",[$name]);$columns=[];$binary=[];foreach($types as $t){$columns[]='"'.$t['column_name'].'"';if($t['data_type']==='bytea')$binary[]=$t['column_name'];}fwrite($file,json_encode(['table'=>$name,'binary'=>$binary,'columns'=>array_column($types,'column_name')],JSON_THROW_ON_ERROR)."\n");$cursor='backup_'.bin2hex(random_bytes(6));$db->rows('DECLARE '.$cursor.' NO SCROLL CURSOR FOR SELECT '.implode(',',$columns).' FROM "'.$name.'"');$count=0;do{$rows=$db->rows('FETCH FORWARD 500 FROM '.$cursor);foreach($rows as $row){foreach($binary as $column){$v=$row[$column];if(is_resource($v))$v=stream_get_contents($v);$row[$column]=$v===null?null:base64_encode($v);}fwrite($file,json_encode(['row'=>$row],JSON_THROW_ON_ERROR)."\n");$count++;}}while($rows);$db->rows('CLOSE '.$cursor);$counts[$name]=$count;}});fclose($file);
            $zip=new \ZipArchive();$zip->open($work.'/archive.zip',\ZipArchive::CREATE|\ZipArchive::OVERWRITE);$manifest=['format'=>1,'created_at'=>date('c'),'database'=>'PostgreSQL data; restore into the matching application schema','tables'=>$counts,'media_inventory'=>['missing'=>$inventory['missing'],'external'=>$inventory['external']],'files'=>[]];$add=function($source,$name)use($zip,&$manifest){$zip->addFile($source,$name);$manifest['files'][$name]=hash_file('sha256',$source);};$add($data,'database.jsonl');$add(ANNAM_ROOT.'/resources/schema.sql','schema.sql');
            foreach(['media'=>Media::root(),'bills'=>ANNAM_ROOT.'/storage/bills'] as $prefix=>$root)if(is_dir($root))foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS)) as $entry){if(!$entry->isFile()||$entry->isLink())continue;$name=$prefix.'/'.substr($entry->getPathname(),strlen(rtrim($root,'/'))+1);$add($entry->getPathname(),$name);}
            $keys=[];foreach(['APP_SECRET','SECRETS_KEY','DJANGO_SECRET_KEY','DATABASE_DSN','DATABASE_USER','DATABASE_PASSWORD','DATABASE_SSLMODE','APP_URL','STORE_SLUG','APP_TIMEZONE','MEDIA_ROOT','PAYMENTS_ENABLED','MESSAGING_ENABLED','REQUIRE_CRON'] as $name)$keys[$name]=getenv($name)?:'';file_put_contents($work.'/keys.json',json_encode($keys,JSON_THROW_ON_ERROR));chmod($work.'/keys.json',0600);$add($work.'/keys.json','recovery/keys.json');$zip->addFromString('MANIFEST.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));$zip->close();self::seal($work.'/archive.zip',$target);return ['tables'=>count($counts),'rows'=>array_sum($counts),'files'=>count($manifest['files']),'missing_media'=>count($inventory['missing']),'encrypted'=>true];
        }finally{if(is_resource($file))fclose($file);self::clean($work);}
    }
    private static function clean(string $path):void {if(!is_dir($path))return;foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($path,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST) as $f)$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());rmdir($path);}
    public static function verify(string $source,?string $extract=null):array {
        $tmp=tempnam(ANNAM_ROOT.'/storage','verify-');try{self::unseal($source,$tmp);$zip=new \ZipArchive();if($zip->open($tmp)!==true)throw new \RuntimeException('Invalid recovery ZIP.');try{$manifest=json_decode($zip->getFromName('MANIFEST.json'),true,512,JSON_THROW_ON_ERROR);foreach($manifest['files'] as $name=>$hash){if(str_contains($name,'..')||str_contains($name,'\\')||!preg_match('~^(database\.(?:jsonl|sqlite)|schema\.sql|media/.+|bills/.+|recovery/(?:keys|installation)\.json)$~D',$name))throw new \RuntimeException('Unsafe archive name.');$stream=$zip->getStream($name);if(!$stream)throw new \RuntimeException('Missing archive file.');$ctx=hash_init('sha256');hash_update_stream($ctx,$stream);fclose($stream);if(!hash_equals($hash,hash_final($ctx)))throw new \RuntimeException('Backup checksum mismatch.');}if($extract){if(!str_starts_with($extract,'/')||str_contains($extract,'public_html')||str_starts_with($extract,ANNAM_ROOT.'/public/'))throw new \RuntimeException('Use a private absolute extraction path.');if(file_exists($extract))throw new \RuntimeException('Extraction destination must be new and outside public_html.');mkdir($extract,0700,true);foreach(array_keys($manifest['files']) as $name){$dest=$extract.'/'.$name;if(!is_dir(dirname($dest)))mkdir(dirname($dest),0700,true);$in=$zip->getStream($name);$out=fopen($dest,'xb');chmod($dest,0600);stream_copy_to_stream($in,$out);fclose($in);fclose($out);}file_put_contents($extract.'/MANIFEST.json',json_encode($manifest));}return ['verified'=>true,'tables'=>count($manifest['tables']),'rows'=>array_sum($manifest['tables']),'files'=>count($manifest['files'])];}finally{$zip->close();}}finally{unlink($tmp);}
    }
    public static function restoreData(Database $db,string $data):void {
        // Restore is deliberately limited to an empty, separately provisioned schema.
        $db->transaction(function()use($db,$data){$db->rows('SET CONSTRAINTS ALL DEFERRED');$tables=$db->rows("SELECT tablename FROM pg_tables WHERE schemaname='public'");foreach($tables as $r)if($db->one('SELECT 1 AS n FROM "'.$r['tablename'].'" LIMIT 1'))throw new \RuntimeException('Restore requires an empty database schema. Existing data was not changed.');
            $file=fopen($data,'rb');$segments=[];try{while(($line=fgets($file))!==false){$entry=json_decode($line,true,512,JSON_THROW_ON_ERROR);if(isset($entry['table']))$segments[$entry['table']]=['meta'=>$entry,'offset'=>ftell($file)];}
            $edges=[];foreach($db->rows("SELECT child.relname AS child,parent.relname AS parent FROM pg_constraint c JOIN pg_class child ON child.oid=c.conrelid JOIN pg_class parent ON parent.oid=c.confrelid JOIN pg_namespace n ON n.oid=child.relnamespace WHERE c.contype='f' AND NOT c.condeferrable AND n.nspname='public'") as $edge)if($edge['child']!==$edge['parent'])$edges[$edge['child']][]=$edge['parent'];$done=[];$visiting=[];$ordered=[];$visit=function($name)use(&$visit,&$done,&$visiting,&$ordered,$edges,$segments){if(isset($done[$name]))return;if(isset($visiting[$name]))throw new \RuntimeException('Nondeferrable database dependency cycle.');$visiting[$name]=true;foreach($edges[$name]??[] as $parent)if(isset($segments[$parent]))$visit($parent);unset($visiting[$name]);$done[$name]=true;$ordered[]=$name;};foreach(array_keys($segments) as $name)$visit($name);
            foreach($ordered as $name){$meta=$segments[$name]['meta'];if(!preg_match('/^[a-z_][a-z0-9_]*$/D',$name))throw new \RuntimeException('Invalid table.');fseek($file,$segments[$name]['offset']);while(($line=fgets($file))!==false){$entry=json_decode($line,true,512,JSON_THROW_ON_ERROR);if(isset($entry['table']))break;$row=$entry['row'];foreach(array_keys($row) as $column)if(!preg_match('/^[a-z_][a-z0-9_]*$/D',$column))throw new \RuntimeException('Invalid column.');$values=[];$expressions=[];foreach($row as $column=>$value){if(in_array($column,$meta['binary'],true)){$expressions[]="decode(?,'base64')";$values[]=$value;}else{$expressions[]='?';$values[]=$value;}}$db->rows('INSERT INTO "'.$name.'" ('.implode(',',array_map(fn($c)=>'"'.$c.'"',array_keys($row))).') OVERRIDING SYSTEM VALUE VALUES('.implode(',',$expressions).')',$values);}}
            }finally{fclose($file);}
            foreach($db->rows("SELECT table_name,column_name FROM information_schema.columns WHERE table_schema='public' AND (column_default LIKE 'nextval(%' OR is_identity='YES')") as $r){$seq=$db->one('SELECT pg_get_serial_sequence(?,?) AS name',[$r['table_name'],$r['column_name']])['name'];if($seq)$db->one('SELECT setval(?,COALESCE((SELECT MAX("'.$r['column_name'].'") FROM "'.$r['table_name'].'"),1),EXISTS(SELECT 1 FROM "'.$r['table_name'].'"))',[$seq]);}
        });
    }
}
